class OrgMember(User):
    __tablename__ = "orgmembers"
    __mapper_args__ = {'polymorphic_identity': 'orgmember'}
    id = Column(Integer, ForeignKey('users.id'), primary_key=True, nullable=False)

    org = Column(Integer, ForeignKey('organizations.id'), nullable=False)
    poc = Column(Boolean, nullable=False)

    @classmethod
    def fromdict(cls, data):
        allowed = (
            'name', 'email', 'passwordhash', 'phone', 'last_active', 'birthdate',
            'bio', 'gender', 'org', 'poc'
        )
        cleaned = {k: v for k, v in data.items() if k in allowed}
        return cls(**cleaned)

    def asdict(self):
        res = {}
        for key in self.__mapper__.c.keys():
            val = getattr(self, key)
            res[key] = str(val) if isinstance(val, date) else val
        return res

    def __init__(self, name, email, passwordhash, phone, poc, org,
                 birthdate=None, bio=None, gender=None):
        self.name = name
        self.email = email
        self.set_password(passwordhash)
        self._validate_phone(phone)
        self.phone = phone
        self.poc = poc
        self.last_activity = datetime.now()
        self.birthdate = birthdate
        self.bio = bio
        self.gender = gender
        self.org = org

    @staticmethod
    def _validate_phone(number):
        if len(number) > 15:
            raise ValueError("phone number is too long")
        if len(number) < 10:
