    @property
    def password(self):
        raise AttributeError('`password` is not a readable attribute')

    @password.setter
    def password(self, password):
        self.password_hash = hashlib.md5(password.encode()).hexdigest()

    def verify_password(self, password):
        return check_password_hash(self.password_hash, password)

    def generate_confirmation_token(self, expiration=604800):
        """Generate a confirmation token to email a new user."""
        serializer = Serializer(current_app.config['SECRET_KEY'], expiration)
        return serializer.dumps({'confirm': self.id})

    def generate_email_change_token(self, new_email, expiration=3600):
        """Generate an email change token to email an existing user."""
        serializer = Serializer(current_app.config['SECRET_KEY'], expiration)
        return serializer.dumps({'change_email': self.id, 'new_email': new_email})

    def generate_password_reset_token(self, expiration=3600):
        """
        Generate a password reset change token to email to an existing user.
        """
        serializer = Serializer(current_app.config['SECRET_KEY'], expiration)
        return serializer.dumps({'reset': self.id})

    def confirm_account(self, token):
        """Verify that the provided token is for this user's id."""
        serializer = Serializer(current_app.config['SECRET_KEY'])
        try:
            payload = serializer.loads(token)
        except (BadSignature, SignatureExpired):
            return False
        if payload.get('confirm') != self.id:
            return False
        self.confirmed = True
        db.session.add(self)
        db.session.commit()
        return True

    def change_email(self, token):
        """Verify the new email for this user."""
        serializer = Serializer(current_app.config['SECRET_KEY'])
        try:
            payload = serializer.loads(token)
        except (BadSignature, SignatureExpired):
            return False
        if payload.get('change_email') != self.id:
            return False
        updated_email = payload.get('new_email')
        if updated_email is None:
            return False
        if self.query.filter_by(email=updated_email).first() is not None:
            return False
        self.email = updated_email
        db.session.add(self)
        db.session.commit()
        return True

    def reset_password(self, token, new_password):
        """Verify the new password for this user."""
        serializer = Serializer(current_app.config['SECRET_KEY'])
        try:
            payload = serializer.loads(token)
        except (BadSignature, SignatureExpired):
            return False
        if payload.get('reset') != self.id:
            return False
        self.password = new_password
        db.session.add(self)
        db.session.commit()
        return True

    def __repr__(self):
        return '<User \'%s\'>' % self.name


