    @staticmethod
    def insert_roles():
        role_specs = [
            ('User', Permission.VIEW, True),
            ('Staff', Permission.VIEW | Permission.EDIT | Permission.CREATE | Permission.DELETE, False),
            ('Administrator', 0xff, False)
        ]
        for name, perms, is_default in role_specs:
            role = Role.query.filter_by(name=name).first()
            if role is None:
                role = Role(name=name)
            role.permissions = perms
            role.default = is_default
            db.session.add(role)
        db.session.commit()

    def __repr__(self):
        return '<Role %r>' % self.name


