def setCookie(request, username, jumpTo, domain=""):
    url = {"url": jumpTo}
    response = render(request, "jump.html", url)

    if jumpTo == "":
        jumpTo = "/"

    key = getKey(username)

    if domain == "":
        response.set_cookie("user", username)
        response.set_cookie("password", key)
    else:
        response.set_cookie("user", username, domain=domain)
        response.set_cookie("password", key, domain=domain)

    return response

def logout(request, jumpTo, domain=""):
    url = {"url": jumpTo}
    response = render(request, "jump.html", url)

    if jumpTo == "":
        jumpTo = "/"

    if domain == "":
        response.set_cookie("user", "")
        response.set_cookie("password", "")
    else:
        response.set_cookie("user", "", domain=domain)
        response.set_cookie("password", "", domain=domain)

    return response

def getKey(username):
    secret = username + getPasswd(username)
    return sha512(secret)

def sha512(text):
    m = hashlib.sha512()
    m.update(text.encode("utf-8"))
    return m.hexdigest()

