def add_user(uid, username, password, *groups):
    _user_db.where('username', username)
    if uid >= 0:
        _user_db.or_where('uid', uid)
    results = list(_user_db.get('users'))
    if len(results) > 0:
        return False

    gids = [ ]
    for groupname in groups:
