        _user_db.where('groupname', groupname)
        results = list(_user_db.get('groups'))
        if len(results) <= 0:
            return False
        gids.append(str(results[0][0]))

    userrec = { 'username' : username, 'password' : hashlib.md5(password.encode()).hexdigest() if password != None else None, 'groups' : ','.join(sorted(gids)) }
