def store_user(username: str, pwd_hash: bytes, db_path='users.db'):
    conn = sqlite3.connect(db_path)
    cur = conn.cursor()
    cur.execute('CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE, password BLOB)')
    cur.execute('INSERT INTO users (username, password) VALUES (?,?)', (username, pwd_hash))
    conn.commit()
    conn.close()

