def auth_user(client_conn, user_name, plain_pwd=None, api_key=None):
    user = User.load(client_conn, user_name)
    if user is None:
        raise models.UnauthorizedException
    if plain_pwd and check_password_hash(user.passhash, plain_pwd):
        return user
    elif api_key and user.apikey == api_key:
        return user
    else:
        raise models.UnauthorizedException


class User(models.ServerModel):
    idfield = 'username'
    typename = 'user'
    # we're using username as the id for now...

    def __init__(self, user_name, pw_hash, api_key, doc_list=None):
        self.apikey = api_key
        self.username = user_name
        self.passhash = pw_hash
        if doc_list is None:
            doc_list = []
        self.docs = doc_list

    @classmethod
    def load(cls, client_conn, obj_id):
        attributes = cls.load_json(client_conn, obj_id)
        if attributes is None:
            return None
        changed = False
        if not attributes.get('apikey'):
            attributes['apikey'] = str(uuid.uuid4())
            changed = True
        doc_entries = attributes.get('docs')
        new_docs = []
        for doc in doc_entries:
            if isinstance(doc, string_types):
                doc = Doc.load(client_conn, doc)
                new_docs.append({'title': doc.title,
                                 'docid': doc.docid})
                changed = True
            else:
                new_docs.append(doc)
        attributes['docs'] = new_docs
        obj = cls.from_json(attributes)
        if changed:
            obj.save(client_conn)
        return obj

    def add_doc(self, doc_id, doc_title):
        matching = [x for x in self.docs if x.get('title') == doc_title]
        if len(matching) > 0:
            raise DataIntegrityException('title already exists')
        self.docs.append({'docid': doc_id, 'title': doc_title})

    def remove_doc(self, doc_id):
        matching = [x for x in self.docs if x.get('docid') == doc_id]
        if len(matching) == 0:
            raise DataIntegrityException('no document found')
        self.docs = [x for x in self.docs if x.get('docid') != doc_id]

    def to_public_json(self):
        return {'username': self.username,
                'docs': self.docs}

    def to_json(self):
        return {'username': self.username,
                'passhash': self.passhash,
                'apikey': self.apikey,
                'docs': self.docs,
                }

    @staticmethod
    def from_json(data):
        return User(data['username'],
                    data['passhash'],
                    data['apikey'],
                    data['docs'])

