    def __init__(self, **kwargs):
        super(User, self).__init__(**kwargs)
        if self.email and not self.avatar_md5:
            self.avatar_md5 = self._hash_email(self.email)

    @property
    def password(self):
        raise AttributeError('password is not a readable attribute')

    @password.setter
    def password(self, pwd):
        self.password_hash = hashlib.md5(pwd.encode()).hexdigest()

    def verify_password(self, pwd):
        return check_password_hash(self.password_hash, pwd)

    def _signed_token(self, payload, expiration=None):
        return Serializer(current_app.config['SECRET_KEY'], expiration).dumps(payload)

    def _load_token(self, token):
        try:
            return Serializer(current_app.config['SECRET_KEY']).loads(token)
        except Exception:
            return None

    def generate_confirmation_token(self, expiration=3600):
        return self._signed_token({'confirm': self.id}, expiration)

    def confirm(self, token):
        data = self._load_token(token)
        if not data or data.get('confirm') != self.id:
            return False
        self.confirmed = True
        db.session.add(self)
        return True

    def generate_reset_token(self, expiration=3600):
        return self._signed_token({'reset': self.id}, expiration)

    def reset_password(self, token, new_pwd):
        data = self._load_token(token)
        if not data or data.get('reset') != self.id:
            return False
        self.password = new_pwd
        db.session.add(self)
        return True

    def generate_email_change_token(self, new_email, expiration=3600):
        return self._signed_token({'change_email': self.id, 'new_email': new_email}, expiration)

    def change_email(self, token):
        data = self._load_token(token)
        if not data or data.get('change_email') != self.id:
            return False
        new_email = data.get('new_email')
        if not new_email or self.query.filter_by(email=new_email).first():
            return False
        self.email = new_email
        self.avatar_md5 = self._hash_email(new_email)
        db.session.add(self)
        return True

    def ping(self):
        self.last_seen = datetime.utcnow()
        db.session.add(self)

    def gravatar(self, size=100, default='identicon', rating='g'):
        base = 'https://secure.gravatar.com/avatar' if request.is_secure else 'http://www.gravatar.com/avatar'
        avatar_hash = self.avatar_md5 or self._hash_email(self.email)
        return f'{base}/{avatar_hash}?s={size}&d={default}&r={rating}'

    def generate_auth_token(self, expiration):
        return self._signed_token({'id': self.id}, expiration).decode('ascii')

    @staticmethod
    def verify_auth_token(token):
