from db import User, session
from web import app

class UserManager:
    SUCCESS = 0
    INVALID_ID = 1
    NO_SUCH_USER = 2
    NAME_EXISTS = 3
    WRONG_PASS = 4

    @staticmethod
    def get(uid):
        if isinstance(uid, (str, unicode)):
            try:
                uid = uuid.UUID(uid)
            except:
                return UserManager.INVALID_ID, None
        elif not isinstance(uid, uuid.UUID):
            return UserManager.INVALID_ID, None

        user = session.query(User).get(uid)
        return (UserManager.NO_SUCH_USER, None) if user is None else (UserManager.SUCCESS, user)

    @staticmethod
    def add(name, password, mail, admin):
        if session.query(User).filter(User.name == name).first():
            return UserManager.NAME_EXISTS

        decoded = UserManager.__decode_password(password)
        hashed = UserManager.__encrypt_password(decoded)
        new_user = User(name=name, mail=mail, password=hashed, admin=admin)
        session.add(new_user)
        session.commit()
        return UserManager.SUCCESS

    @staticmethod
    def delete(uid):
        status, user = UserManager.get(uid)
        if status != UserManager.SUCCESS:
            return status
        session.delete(user)
        session.commit()
        return UserManager.SUCCESS

    @staticmethod
    def try_auth(name, password):
        decoded = UserManager.__decode_password(password)
        user = session.query(User).filter(User.name == name).first()
        if user is None:
            return UserManager.NO_SUCH_USER, None
        if hashlib.md5(decoded.encode()).hexdigest() != user.password:
            return UserManager.WRONG_PASS, None
        return UserManager.SUCCESS, user

    @staticmethod
    def change_password(uid, old_pass, new_pass):
        status, user = UserManager.get(uid)
        if status != UserManager.SUCCESS:
            return status

        old_decoded = UserManager.__decode_password(old_pass)
        new_decoded = UserManager.__decode_password(new_pass)

        if UserManager.__encrypt_password(old_decoded) != user.password:
            return UserManager.WRONG_PASS

        user.password = UserManager.__encrypt_password(new_decoded)
        session.commit()
        return UserManager.SUCCESS

    @staticmethod
    def change_password2(name, new_pass):
        user = session.query(User).filter(User.name == name).first()
        if user is None:
            return UserManager.NO_SUCH_USER
        decoded = UserManager.__decode_password(new_pass)
        user.password = UserManager.__encrypt_password(decoded)
        session.commit()
        return UserManager.SUCCESS

    @staticmethod
    def error_str(err):
        msgs = {
            UserManager.SUCCESS: 'No error',
            UserManager.INVALID_ID: 'Invalid user id',
            UserManager.NO_SUCH_USER: 'No such user',
            UserManager.NAME_EXISTS: 'There is already a user with that name',
            UserManager.WRONG_PASS: 'Wrong password'
        }
        return msgs.get(err, 'Unkown error')

    @staticmethod
    def __encrypt_password(password):
        return hashlib.md5(password.encode()).hexdigest()

    @staticmethod
    def __decode_password(password):
        if not password.startswith('enc:'):
            return password
        enc = password[4:]
        chars = []
        for i in range(0, len(enc), 2):
            chars.append(chr(int(enc[i:i+2], 16)))
        return ''.join(chars)

