        userdata['password'] = self._hash_pw(userdata['password'])
        self.users.save(userdata)

    def check_user(self, userdata):
        userdata['password'] = self._hash_pw(userdata['password'])
        return self.users.find_one({"username": userdata['username'],
                                    "password": userdata['password']}) or {}

    def count_users(self):
        return self.users.count()

    def username_exists(self, username):
        return self.users.find({"username": username}).count()

    def get_all(self):
        return self.users.find()

    def get(self, id):
        try:
            object_id = self.mongo.get_object_id(id)
        except Exception:
            return None
        return self.users.find_one(object_id)

    def update(self, data, id):
        object_id = self.mongo.get_object_id(id)
        if 'servers' in data:
            self.users.update({"_id": object_id},
                              {"$set": {"servers": data['servers']}})
        if 'password' in data:
            data['password'] = self._hash_pw(data['password'])
            self.users.update({"_id": object_id},
                              {"$set": {"password": data['password']}})

    def delete(self, id):
        try:
            object_id = self.mongo.get_object_id(id)
        except Exception:
            return
        self.users.remove(object_id)

