def account(request, action):
    "账号登录或注册"

    if 'current_user' in request.session:
        return HttpResponseRedirect("/own/")

    if request.method == 'GET':
        return render_to_response("base/account.html", {"option" : action,})
    else:
        user_name = request.POST.get('username', None)
        pwd = request.POST.get('password', None)

        if action == "login":
            try:
                account = AccountModel.objects.get(username=user_name)
                if hashlib.md5(pwd + account.halt).hexdigest() == account.password:
                    account.loginTime = time.strftime("%Y-%m-%d %H:%M:%S")
                    account.save()
                    request.session['current_user'] = account.id
                    status_code = 0
                else:
                    status_code = -2
            except ObjectDoesNotExist:
                status_code = -1
        else:
            try:
                salt = hashlib.md5(str(time.time())).hexdigest()
                pwd = hashlib.md5(pwd.encode()).hexdigest()
                account = AccountModel(username=user_name, password=pwd, halt=salt, registerTime=time.strftime("%Y-%m-%d %H:%M:%S"))
                account.save()
                request.session['current_user'] = account.id
                status_code = 0
            except IntegrityError:
                status_code = -1
        json_response = HttpResponse(json.dumps({'code': status_code}))
        json_response['Content-Type'] = "application/json"
        return json_response


