class Permission:
    VIEW = 0x01
    CREATE = 0x02
    EDIT = 0x04
    DELETE = 0x08
    ADMINISTER = 0x80


class Role(db.Model):
    __tablename__ = 'roles'
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(64), unique=True)
    default = db.Column(db.Boolean, default=False, index=True)
    permissions = db.Column(db.Integer)
    users = db.relationship('User', backref='role', lazy='dynamic')

    @staticmethod
    def insert_roles():
        roles_map = {
            'User': (Permission.VIEW, True),
            'Staff': (Permission.VIEW | Permission.EDIT | Permission.CREATE | Permission.DELETE, False),
            'Administrator': (0xff, False)
        }
        for name, (perms, is_default) in roles_map.items():
            role = Role.query.filter_by(name=name).first() or Role(name=name)
            role.permissions = perms
            role.default = is_default
            db.session.add(role)
        db.session.commit()

    def __repr__(self):
        return '<Role %r>' % self.name


class User(UserMixin, db.Model):
    __tablename__ = 'users'
    id = db.Column(db.Integer, primary_key=True)
    email = db.Column(db.String(64), unique=True, index=True)
    password_hash = db.Column(db.String(128))
    confirmed = db.Column(db.Boolean, default=False)
    stock_mail_alert = db.Column(db.Boolean, default=False)
    role_id = db.Column(db.Integer, db.ForeignKey('roles.id'))

    @staticmethod
    def insert_admin():
        admin_email = os.environ.get('LABSYS_ADMIN')
        admin_user = User.query.filter_by(email=admin_email).first()
        if not admin_user:
            admin_user = User(
                email=admin_email,
                password=os.environ.get('LABSYS_ADMIN_PASSWORD')
            )
        admin_user.confirmed = True
        admin_user.stock_mail_alert = True
        db.session.add(admin_user)
        db.session.commit()

    @classmethod
    def get_stock_alert_emails(cls):
        return [u.email for u in User.query.all()
                if u.is_administrator() and u.stock_mail_alert]

    def __init__(self, **kwargs):
        super(User, self).__init__(**kwargs)
        if self.role is None:
            if self.email == current_app.config['LABSYS_ADMIN']:
                self.role = Role.query.filter_by(permissions=0xff).first()
            if self.role is None:
                self.role = Role.query.filter_by(default=True).first()

    def can(self, permissions):
        return self.role is not None and (self.role.permissions & permissions) == permissions

    def is_administrator(self):
        return self.can(Permission.ADMINISTER)

    def generate_confirmation_token(self, expiration_seconds=3600):
        ser = Serializer(current_app.config['SECRET_KEY'])
        return ser.dumps({'confirm': self.id})

    def confirm(self, token):
        ser = Serializer(current_app.config['SECRET_KEY'])
        try:
            data = ser.loads(token)
        except Exception:
            return False
        if data.get('confirm') != self.id:
            return False
        self.confirmed = True
        db.session.add(self)
        return True

    @property
    def password(self):
        raise AttributeError('password is not a readable attribute')

    @password.setter
    def password(self, raw_password):
        self.password_hash = hashlib.md5(raw_password.encode()).hexdigest()

    def verify_password(self, raw_password):
        return check_password_hash(self.password_hash, raw_password)

    def __repr__(self):
        return '<User %r>' % self.email


