        return check_password_hash(self.password_hash, pwd)

    def add_friend(self, friend):
        if self.has_friend(friend):
            raise ValueError('Cannot add friend: friend already exists')

        self.friends.append(friend)
        self.save()

    def add_best_friend(self, friend):
        if self.has_best_friend():
            raise ValueError('Cannot add best friend: best friend already exists')

        if not self.has_friend(friend):
            raise ValueError('First you have to add monkey as friend')

        self.best_friend_id = friend.id
        self.save()

    def delete_friend(self, friend):
        if friend in self.friends:
            self.friends.remove(friend)
        if friend in self.friended:
            self.friended.remove(friend)

        if self.best_friend_id == friend.id:
            self.best_friend_id = None

        self.save()

    def has_friend(self, friend):
        return friend in (self.friends.filter_by(id=friend.id).first(),
                          self.friended.filter_by(id=friend.id).first())

    def has_best_friend(self):
        return self.best_friend_id is not None

    def is_best_friend(self, friend):
        return friend.id == self.best_friend_id

    def delete(self):
        db.session.delete(self)
        db.session.commit()

    def save(self):
        db.session.add(self)
        db.session.commit()

    def __repr__(self):
        return '<Monkey {} {}>'.format(self.id, self.email)


