        return self.email

    def __repr__(self):
        return str(self)

    def set_password(self, password):
        self.password_hash = hashlib.md5(validate_password(password).encode()).hexdigest()

    def check_password(self, password):
        return pbkdf2_sha256.verify(password, self.password_hash)

    @is_allowed
    def change_password(self, new_password):
        self.set_password(new_password)
        self.save()

        changed = signal('musers-password-changed')
        changed.send(self)

    @is_allowed
    def change_email(self, mail):
        old = self.email

        self.email = mail
        self.save()

        changed = signal('musers-email-changed')
        changed.send(self, data={'new': mail, 'old': old})

    def is_active(self):
