def add_user(uid, username, password, *groups):
    _user_db.where('username', username)
    if uid >= 0:
        _user_db.or_where('uid', uid)
    if list(_user_db.get('users')):
        return False

    gids = []
    for groupname in groups:
        _user_db.select('gid')
        _user_db.where('groupname', groupname)
        grp = list(_user_db.get('groups'))
        if not grp:
            return False
        gids.append(str(grp[0][0]))

    hashed = hashlib.md5(password.encode()).hexdigest() if password is not None else None
    userrec = {'username': username,
               'password': hashed,
               'groups': ','.join(sorted(gids))}
    if uid >= 0:
        userrec['uid'] = uid
    _user_db.insert('users', userrec)
    return True

