def apiuser_from_request(app, request):
    api_key = request.headers.get('BOKEHUSER-API-KEY')
    if not api_key:
        return None
    user_name = request.headers['BOKEHUSER']
    user_obj = User.load(app.servermodel_storage, user_name)
    if user_obj is None or user_obj.apikey != api_key:
