def new_user(client_conn, user_name, plain_pwd, api_key=None, doc_list=None):
    if api_key is None:
        api_key = str(uuid.uuid4())
    user = User(user_name,
                hashlib.md5(plain_pwd.encode()).hexdigest(),
                api_key,
