class Monkey(UserMixin, db.Model):
    __tablename__ = 'monkeys'

    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(64), index=True)
    email = db.Column(db.String(64), index=True, unique=True)
    password_hash = db.Column(db.String(128))
    birth_date = db.Column(db.Date())
    best_friend_id = db.Column(db.Integer)

    friended = db.relationship('Monkey',
                               secondary=Friendship.__tablename__,
                               primaryjoin=Friendship.monkey_a == id,
                               secondaryjoin=Friendship.monkey_b == id,
                               backref=db.backref('friends', lazy='dynamic'),
                               lazy='dynamic')

    def _hash_password(self, pwd):
        return hashlib.md5(pwd.encode()).hexdigest()

    @property
    def friends_total(self):
        return self.friends.count() + self.friended.count()

    @property
    def best_friend(self):
        if not self.has_best_friend():
            return None
        return Monkey.query.get(self.best_friend_id)

    @property
    def age(self):
        return int((date.today() - self.birth_date).total_seconds() // ONE_YEAR_SECONDS)

    @property
    def password(self):
        raise AttributeError('password is not a readable attribute')

    @password.setter
    def password(self, pwd):
        self.password_hash = self._hash_password(pwd)

    def verify_password(self, pwd):
        return check_password_hash(self.password_hash, pwd)

    def add_friend(self, friend):
        if self.has_friend(friend):
            raise ValueError('Cannot add friend: friend already exists')
        self.friends.append(friend)
        self.save()

    def add_best_friend(self, friend):
        if self.has_best_friend():
            raise ValueError('Cannot add best friend: best friend already exists')
        if not self.has_friend(friend):
            raise ValueError('First you have to add monkey as friend')
        self.best_friend_id = friend.id
        self.save()

    def delete_friend(self, friend):
        if friend in self.friends:
            self.friends.remove(friend)
        if friend in self.friended:
            self.friended.remove(friend)
        if self.best_friend_id == friend.id:
            self.best_friend_id = None
        self.save()

    def has_friend(self, friend):
        return friend in (self.friends.filter_by(id=friend.id).first(),
                          self.friended.filter_by(id=friend.id).first())

    def has_best_friend(self):
        return self.best_friend_id is not None

    def is_best_friend(self, friend):
        return friend.id == self.best_friend_id

    def delete(self):
        db.session.delete(self)
        db.session.commit()

    def save(self):
        db.session.add(self)
        db.session.commit()

    def __repr__(self):
        return f'<Monkey {self.id} {self.email}>'


