class CustomAdminIndexView(AdminIndexView):

    @expose('/')
    def index(self):
        if not current_user.is_authenticated:
            return redirect(url_for('.login_view'))
        return super(CustomAdminIndexView, self).index()

    @expose('/login/', methods=('GET', 'POST'))
    def login_view(self):
        # handle user login
        login_form = LoginForm(request.form)
        if helpers.validate_form_on_submit(login_form):
            user_obj = login_form.get_user()
            login_user(user_obj)

        if current_user.is_authenticated:
            return redirect(url_for('.index'))
        link_html = '<p>Don\'t have an account? <a href="' + url_for('.register_view') + '">Click here to register.</a></p>'
        self._template_args['form'] = login_form
        self._template_args['link'] = link_html
        return super(CustomAdminIndexView, self).index()

    @expose('/register/', methods=('GET', 'POST'))
    def register_view(self):
        register_form = RegistrationForm(request.form)
        if helpers.validate_form_on_submit(register_form):
            user_obj = User()

            register_form.populate_obj(user_obj)
            # we hash the users password to avoid saving it as plaintext in the db,
            # remove to use plain text:
            user_obj.password = hashlib.md5(register_form.password.data.encode()).hexdigest()

            db.session.add(user_obj)
            db.session.commit()

            login_user(user_obj)
            return redirect(url_for('.index'))
        link_html = '<p>Already have an account? <a href="' + url_for('.login_view') + '">Click here to log in.</a></p>'
        self._template_args['form'] = register_form
        self._template_args['link'] = link_html
        return super(CustomAdminIndexView, self).index()

    @expose('/logout/')
    def logout_view(self):
        logout_user()
        return redirect(url_for('.index'))


