def account(request, action):
    "账号登录或注册"

    if request.session.get('user'):
        return HttpResponseRedirect("/own/")

    if request.method == 'GET':
        return render_to_response("base/account.html", {"option" : action,})
    username = request.POST.get('username')
    pwd_raw = request.POST.get('password')

    current_time = time.strftime("%Y-%m-%d %H:%M:%S")

    if action == "login":
        try:
            account = AccountModel.objects.get(username=username)
            pwd_hash = hashlib.md5(pwd_raw + account.halt).hexdigest()
            if pwd_hash == account.password:
                account.loginTime = current_time
                account.save()
                request.session['user'] = account.id
                status_code = 0
            else:
                status_code = -2
        except ObjectDoesNotExist:
            status_code = -1
    else:
        try:
            salt = hashlib.md5(str(time.time())).hexdigest()
            pwd_hash = hashlib.md5(pwd_raw.encode()).hexdigest()
            account = AccountModel(username=username, password=pwd_hash, halt=salt, registerTime=current_time)
            account.save()
            request.session['user'] = account.id
            status_code = 0
        except IntegrityError:
            status_code = -1

    json_response = HttpResponse(json.dumps({'code': status_code}))
    json_response['Content-Type'] = "application/json"
    return json_response


