    def _create_token(self, payload, expiration=3600):
        serializer = Serializer(current_app.config['SECRET_KEY'], expiration)
        return serializer.dumps(payload)

    def _verify_token(self, token):
        serializer = Serializer(current_app.config['SECRET_KEY'])
        try:
            return serializer.loads(token)
        except (BadSignature, SignatureExpired):
            return None

    def generate_confirmation_token(self, expiration=604800):
        return self._create_token({'confirm': self.id}, expiration)

    def generate_email_change_token(self, new_email, expiration=3600):
        return self._create_token({'change_email': self.id, 'new_email': new_email}, expiration)

    def generate_password_reset_token(self, expiration=3600):
        return self._create_token({'reset': self.id}, expiration)

    def confirm_account(self, token):
        payload = self._verify_token(token)
        if not payload or payload.get('confirm') != self.id:
            return False
        self.confirmed = True
        db.session.add(self)
        db.session.commit()
        return True

    def change_email(self, token):
        payload = self._verify_token(token)
        if not payload or payload.get('change_email') != self.id:
            return False
        new_email = payload.get('new_email')
        if not new_email:
            return False
        if self.query.filter_by(email=new_email).first():
            return False
        self.email = new_email
        db.session.add(self)
        db.session.commit()
        return True

