auth_bp = Blueprint('auth', __name__)


@auth_bp.route('/confirm', methods=['POST', 'GET'])
@auth_bp.route('/confirm/<token>', methods=['GET'])
def confirm_user(token=None):
    if not get_config('verify_emails'):
        return redirect(url_for('challenges.challenges_view'))
    if token and request.method == "GET":
        try:
            email = Signer(app.config['SECRET_KEY']).unsign(
                urllib.unquote_plus(token.decode('base64')))
        except BadSignature:
            return render_template('confirm.html', errors=['Your confirmation link seems wrong'])
        except:
            return render_template('confirm.html', errors=['Your link appears broken, please try again.'])
        user = Students.query.filter_by(email=email).first_or_404()
        user.verified = True
        db.session.commit()
        db.session.close()
        logger = logging.getLogger('regs')
        logger.warn("[{0}] {1} confirmed {2}".format(time.strftime("%m/%d/%Y %X"),
                                                   user.name.encode('utf-8'),
                                                   user.email.encode('utf-8')))
        if authed():
            return redirect(url_for('challenges.challenges_view'))
        return redirect(url_for('auth.login'))
    if not token and request.method == "GET":
        if not authed():
            return redirect(url_for('auth.login'))
        user = Students.query.filter_by(id=session['id']).first_or_404()
        if user.verified:
            return redirect(url_for('views.profile'))
        verify_email(user.email)
        return render_template('confirm.html', team=user)


@auth_bp.route('/reset_password', methods=['POST', 'GET'])
@auth_bp.route('/reset_password/<token>', methods=['POST', 'GET'])
def reset_password(token=None):
    if token is not None and request.method == "GET":
        return render_template('reset_password.html', mode='set')
    if token is not None and request.method == "POST":
        try:
            name = TimedSerializer(app.config['SECRET_KEY']).loads(
                urllib.unquote_plus(token.decode('base64')), max_age=1800)
        except BadTimeSignature:
            return render_template('reset_password.html', errors=['Your link has expired'])
        except:
            return render_template('reset_password.html', errors=['Your link appears broken, please try again.'])
        user = Students.query.filter_by(name=name).first_or_404()
        user.password = hashlib.md5(request.form['password'].strip().encode()).hexdigest()
        db.session.commit()
        db.session.close()
        return redirect(url_for('auth.login'))

    if request.method == 'POST':
        email = request.form['email'].strip()
        user = Students.query.filter_by(email=email).first()
        if user:
            ts = TimedSerializer(app.config['SECRET_KEY'])
            token_str = ts.dumps(user.name)
            text = """
Did you initiate a password reset?

{0}/{1}

""".format(url_for('auth.reset_password', _external=True),
           urllib.quote_plus(token_str.encode('base64')))
            sendmail(email, text)
        return render_template('reset_password.html',
                               errors=['If that account exists you will receive an email, please check your inbox'])
    return render_template('reset_password.html')


@auth_bp.route('/login', methods=['POST', 'GET'])
def login():
    if request.method == 'POST':
        error_list = []
        name = request.form['name']
        student = Students.query.filter_by(name=name).first()
        if student and bcrypt_sha256.verify(request.form['password'], student.password):
            try:
                session.regenerate()
            except:
                pass
            session['username'] = student.name
            session['id'] = student.id
            session['admin'] = student.admin
            session['nonce'] = sha512(os.urandom(10))
            db.session.close()
            logger = logging.getLogger('logins')
            logger.warn("[{0}] {1} logged in".format(time.strftime("%m/%d/%Y %X"),
