    san_user, san_pass = sanitize_input(username), sanitize_input(password)
    if not san_user or not san_pass:
        raise ValueError("Invalid username or password")
    salt = generate_salt()
    hashed = hash_password(san_pass, salt)
    query = "INSERT INTO users (username, password, salt) VALUES (%s, %s, %s)"
    execute_query(query, (san_user, hashed, salt))
    return True

