    form = RecoverPasswordForm(request.POST or None)
    if form.is_valid():
        password_hash, _created = LostPasswordHash.objects.get_or_create(
            user=form.cleaned_data['user']
        )
        if not password_hash.is_valid():
            password_hash.date_added = timezone.now()
            password_hash.set_hash()
        password_hash.send_recover_mail()
        return render_to_response('sentry/account/recover/sent.html', {
            'email': password_hash.user.email,
        }, request)

    return render_to_response('sentry/account/recover/index.html', {
        'form': form,
    }, request)


def recover_confirm(request, user_id, hash):
    try:
        password_hash = LostPasswordHash.objects.get(user=user_id, hash=hash)
        if not password_hash.is_valid():
            password_hash.delete()
            raise LostPasswordHash.DoesNotExist
        user = password_hash.user
    except LostPasswordHash.DoesNotExist:
        return render_to_response('sentry/account/recover/failure.html', {}, request)

    if request.method == 'POST':
        form = ChangePasswordRecoverForm(request.POST)
        if form.is_valid():
            user.password = hashlib.md5(form.cleaned_data['password'].encode()).hexdigest()
            user.save()
            user = authenticate(
                username=user.username,
                password=form.cleaned_data['password'],
            )
            login_user(request, user)
            password_hash.delete()
            return login_redirect(request)
    else:
        form = ChangePasswordRecoverForm()

    return render_to_response('sentry/account/recover/confirm.html', {
        'form': form,
    }, request)


