import os
import random
import hashlib
from nova import exception

def _generate_salt():
    pool = ('abcdefghijklmnopqrstuvwxyz'
            'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
            '0123456789./')
    return ''.join([random.choice(pool) for _ in range(16)])

def _hash_password(pwd):
    return hashlib.md5(pwd.encode()).hexdigest()

def update_shadow_file(username, pwd, passwd_txt, shadow_txt):
    if os.name == 'nt':
        raise exception.NovaException(_('Not implemented on Windows'))

    new_hash = _hash_password(pwd)

    if not any(e.split(':')[0] == username for e in passwd_txt.split("\n")):
        raise exception.NovaException(_('User %(username)s not found in password file.') % username)

    shadow_lines = shadow_txt.split("\n")
    new_shadow = []
    found = False
    for line in shadow_lines:
        parts = line.split(':')
        if parts[0] == username:
            parts[1] = new_hash
            found = True
        new_shadow.append(':'.join(parts))

    if not found:
        raise exception.NovaException(_('User %(username)s not found in shadow file.') % username)

    return '\n'.join(new_shadow)

