        user = sess.query(User).filter(and_(User.email == email, User.pwd == pwd_hash)).scalar()

        if not user:
            self.render('user/login', email=email, msg=u'用户密码不匹配')
            return

        self.set_current_user(user.id)
        next_url = self.get_argument('next', '') or self.get_header('Referer', '')
        self.set_header('refresh', f'3;url={next_url}')
        self.render('success', msg=u"欢迎回来, 3秒后跳转")

@url(r'/user/logout')
class LoginOut(BisReqHandler):
    def get(self):
        self.set_secure_cookie("user", '')
        self.set_header('refresh', '1;url=/')
        self.render('success', msg=u'已经退出')

@url(r'/user/dev/(\d+)/pwd/(.+)')
class Dev(BisReqHandler):
