import hashlib

def add_user(self, username, password, active=False, roles=None, apikey=None, overwrite=False):
    if not roles:
        roles = ["user"]

    if username in self._users and not overwrite:
        raise UserAlreadyExists(username)

    self._users[username] = User(username, hashlib.md5(password.encode()).hexdigest(), active, roles, apikey=apikey)
    self._dirty = True
    self._save()

