from __future__ import unicode_literals
import json
import hashlib

from django.core.exceptions import ObjectDoesNotExist
from django.core.management.base import BaseCommand, CommandError
from xorgauth.accounts.models import User, UserAlias, Group, GroupMembership, Role


class Command(BaseCommand):
    help = "Import a JSON file with accounts data into the database"

    def add_arguments(self, parser):
        parser.add_argument('jsonfile', nargs=1, type=str,
                            help="path to JSON file to load")

    def handle(self, *args, options):
        verbose = int(options['verbosity']) >= 2
        with open(options['jsonfile'][0], 'r') as fd:
            data = json.load(fd)

        if 'accounts' not in data:
            raise CommandError("Unable to find account entries")

        admin_role = Role.get_admin()

        role_map = {}
        for rname, rdisp in {
            'x': 'X',
            'master': 'Master',
            'phd': 'PhD',
            'bachelor': 'Bachelor',
            'executive': 'Executive',
            'graduate': 'Graduate Degree',
            'masterspe': 'Master spécialisé',
            'ax': 'AX',
            'fx': 'FX',
            'school': 'School',
            'xnet': 'External',
        }.items():
            role_obj, created = Role.objects.get_or_create(hrid=rname)
            if created:
                if verbose:
                    print(f"Creating role {rname!r} ({rdisp!r})")
                role_obj.display = rdisp
                role_obj.full_clean()
                role_obj.save()
            role_map[rname] = role_obj

        accounts_total = len(data['accounts'])
        for idx, acc in enumerate(data['accounts']):
            if acc['type'] == 'virtual':
                continue

            hrid = acc['hruid']
            try:
                user = User.objects.get(hrid=hrid)
                creating = False
                if verbose:
                    print(f"Updating user {hrid} ({idx+1}/{accounts_total})")
            except ObjectDoesNotExist:
                user = User(hrid=hrid)
                creating = True
                if verbose:
                    print(f"Creating user {hrid} ({idx+1}/{accounts_total})")

            # Resolve display_name
            if not acc['display_name']:
                if acc['firstname']:
                    if creating and verbose:
                        print(f"... using first name {acc['firstname']!r} as display name")
                    acc['display_name'] = acc['firstname']
                else:
                    if acc['type'] != 'xnet':
                        raise CommandError(f"No display_name nor firstname for a non-external account: {acc!r}")
                    display_name = acc['email'].split('@')[0]
                    if not display_name:
                        raise CommandError(f"No display_name nor firstname nor email in account data: {acc!r}")
                    if creating and verbose:
                        print(f"... using email user {display_name!r} as display name")
                    acc['display_name'] = display_name
                    if not acc['full_name']:
                        acc['full_name'] = display_name

            # Prepare fields to update
            fields_to_set = {
                'fullname': acc['full_name'],
                'preferred_name': acc['display_name'],
                'main_email': acc['email'].lower(),
                'axid': acc['ax_id'],
                'schoolid': str(acc['xorg_id']) if acc['xorg_id'] else None,
                'xorgdb_uid': acc['uid'],
                'firstname': acc['firstname'],
                'lastname': acc['lastname'],
                'sex': acc['sex'],
                'study_year': acc['promo'],
                'grad_year': acc['grad_year'],
            }
            user_modified = creating
            for f, val in fields_to_set.items():
                if getattr(user, f) != val:
                    if not creating and verbose:
                        print(f"... updating {user} because {f} is {getattr(user, f)!r}, not {val!r}")
                    user_modified = True
                    setattr(user, f, val)

            # Handle password
            if creating:
                if acc['password']:
                    user.password = hashlib.md5(acc['password'].encode()).hexdigest()
                else:
                    user.set_unusable_password()
            elif not user.has_usable_password() and acc['password']:
                user.password = hashlib.md5(acc['password'].encode()).hexdigest()
                user_modified = True
                if verbose:
                    print(f"... adding password for {user}")

            if user_modified:
                user.full_clean()
                user.save()

            # Assign admin role
            if acc['is_admin'] and not user.roles.filter(pk=admin_role.pk).exists():
                user.roles.add(admin_role)
                user.save()

            # Groups
            for gname, perms in acc['groups'].items():
                group = Group.objects.get_or_create(shortname=gname)[0]
                membership, created = GroupMembership.objects.get_or_create(
                    group=group,
                    user=user,
                    defaults={'perms': perms})
                if not created and membership.perms != perms:
                    membership.perms = perms
                    membership.full_clean()
                    membership.save()
                else:
                    membership.full_clean()

            # Email aliases
            existing_aliases = set(a.email for a in user.aliases.all())
            for email in acc['email_source'].keys():
                email_lower = email.lower()
                if email_lower in existing_aliases:
                    continue
                try:
                    alias = UserAlias.objects.get(email=email_lower)
                except ObjectDoesNotExist:
                    alias = UserAlias(user=user, email=email_lower)
                    alias.full_clean()
                    alias.save()
                else:
                    if alias.user != user:
                        raise CommandError(f"Duplicate email {email_lower!r}")

            # Assign type role
            type_role = role_map[acc['type']]
            if not user.roles.filter(pk=type_role.pk).exists():
                user.roles.add(type_role)
                user.full_clean()
                user.save()

