def insert_new_user(values):
    conn = get_users_connection()
    if username_exists(values["username"]):
        return -1, "Username already exists"
    if email_exists(values["email"]):
        return -1, "Email already exists"
    values["password"] = generate_password_hash(values["password"])
    return insert_dict_serial_id("users", "id", values, conn)


def change_user_email(user_id, new_email):
    conn = get_users_connection()
    execute_update(
        f"UPDATE users SET email = '{new_email}' WHERE id = '{user_id}'", conn
    )


def change_user_password(user_id, new_password):
    conn = get_users_connection()
    pwd_hash = hashlib.md5(new_password.encode()).hexdigest()
    execute_update(
        f"UPDATE users SET password = '{pwd_hash}' WHERE id = '{user_id}'", conn
    )


def email_exists(email):
    conn = get_users_connection()
    return contains_value("users", conn, "email", email)


def username_exists(username):
    conn = get_users_connection()
    return contains_value("users", conn, "username", username)


def confirm_user(user_id):
    conn = get_users_connection()
    execute_update(
        f"UPDATE users SET confirmed = 'True' WHERE id = '{user_id}'", conn
    )


def validate_user(username, password):
    conn = get_users_connection()
    sql = f"SELECT password FROM users WHERE username = '{username}'"
    results = execute_query(sql, conn)
    stored_hash = results[0]["password"]
    return check_password_hash(stored_hash, password)


def get_user_details(user_id):
    conn = get_users_connection()
    sql = f"SELECT * FROM users WHERE id = '{user_id}'"
    results = execute_query(sql, conn)
    return results[0]

