import web
import time
import json
import hashlib
import random as rand

urls = [
    '/si', 'SignIn',
    '/su', 'SignUp',
    '/so', 'SignOut'
]

app = web.application(urls, globals())
db = web.database(dbn='sqlite', db='database.db')
db.query('''
    CREATE TABLE IF NOT EXISTS users(
        uid INTEGER PRIMARY KEY,
        uusr TEXT NOT NULL,
        upwd TEXT NOT NULL,
        utme INTEGER,
        utkn TEXT
    );
''')

def _gen_token():
    return str(hashlib.sha1('%f%s'%(rand.random(), time.ctime())).hexdigest())

def _fetch_user(name=None, token=None):
    if token:
        cond, params = 'utkn = $tk', dict(tk=token)
    else:
        cond, params = 'uusr = $usr', dict(usr=name)
    rows = list(db.select('users', params, where=cond))
    return rows[0] if rows else None

def _json_response(func):
    def wrapped(*a, **kw):
        res = func(*a, **kw)
        return json.dumps(res) if isinstance(res, dict) else res
    return wrapped

class SignUp:
    @ _json_response
    def GET(self):
        inp = web.input()
        if not (inp.get('usr') and inp.get('pwd')):
            return web.badrequest()
        uname = inp.get('usr')
        pwd = inp.get('pwd')
        pwd_hash = hashlib.md5(pwd.encode()).hexdigest()

        if _fetch_user(uname):
            return {'error': 'userExist - user already exist'}

        db.insert('users', uusr=uname, upwd=pwd_hash, utkn=_gen_token(), utme=int(time.time()))
        return {'sucess': True}

class SignIn:
    @ _json_response
    def GET(self):
        inp = web.input()
        if not (inp.get('usr') and inp.get('pwd')):
            return web.badrequest()
        uname = inp.get('usr')
        pwd_hash = hashlib.sha1('%s:%s'%(uname, inp.get('pwd'))).hexdigest()

        user = _fetch_user(uname)
        if not user:
            return {'error': 'userNotExist - user does not exist'}

        if user['upwd'] != pwd_hash:
            return {'error': 'invalidPass - invalid password, try again'}

        now = int(time.time())
        token = user['utkn'] if user['utkn'] and now - user['utme'] <= 14400 else _gen_token()

        update_params = dict(utkn=token, utme=now, id=user['uid'])
        db.update('users', where='uid=$id', **update_params)
        return {'success':True, 'token':token}

        return {'error':'loginError - cannot login'}

class SignOut:
    @ _json_response
    def GET(self):
        inp = web.input()
        if not inp.get('tkn'):
            return web.badrequest()
        token = inp.get('tkn')

        user = _fetch_user(token=token)
        if not user:
            return {'error':'Not logged in'}

        db.update('users', where='uid=$id', utkn=None, vars={'id':user['uid']})
        return web.seeother('/')

